insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','aceite','Aceite de motor y filtro','Cambiar',30000,24,null,false,'fabricante','Plan Renault','Renault (vía Haynes): cada 30.000 km o 2 años. Los motores fabricados hasta octubre de 2000 tenían 20.000 km o 2 años; si el tuyo es de esa época, sigue ese plazo.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','filtro-aire','Filtro de aire del motor','Cambiar',30000,24,null,false,'fabricante','Plan Renault','Haynes da 30.000 km (con 2 o 4 años según el año de fabricación). Ponemos 2 años, el más prudente.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'fabricante','Plan Renault','Renault (vía Haynes): cada 30.000 km o 2 años.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','bujias','Bujías','Cambiar',60000,null,null,false,'fabricante','Plan Renault','Renault (vía Haynes): cada 60.000 km.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','distribucion','Correa de distribución (kit con tensor)','Cambiar',120000,60,null,false,'fabricante','Plan Renault','Renault (vía Haynes): cada 120.000 km o 5 años, lo que llegue antes. Si se rompe, el motor se daña: no la alargues. Aprovecha para cambiar la bomba de agua.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','correa','Correa de accesorios (alternador)','Cambiar',120000,60,null,false,'gemelo','Plan Clio II 1.2 (gemelo)','El plan del Clio II 1.2 8V (mismo motor D7F) la cambia junto con la distribución. Revisa grietas en cada revisión.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','frenos-liquido','Líquido de frenos','Cambiar',120000,48,null,false,'fabricante','Plan Renault','Renault (vía Haynes): cada 4 años (o 120.000 km).',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','refrigerante','Líquido refrigerante','Cambiar',120000,48,null,false,'gemelo','Plan Clio II 1.2 (gemelo)','Haynes no da plazo de cambio para el Kangoo; el plan del Clio II 1.2 (mismo motor) lo cambia a los 120.000 km o 4 años.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',30000,12,null,false,'aproximado','Plazo aproximado','Revisar en cada revisión. Cambiar pastillas con menos de 3 mm de material. En furgonetas cargadas o en ciudad se gastan antes.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','frenos-traseros','Revisar frenos traseros (tambor o disco según versión)','Revisar',40000,24,null,false,'aproximado','Plazo aproximado','La mayoría lleva tambor detrás; algunas versiones llevan disco. Revisar desgaste y ajuste del freno de mano.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no de Renault. Presión una vez al mes (más si vas cargado: mira la etiqueta del marco de la puerta). Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar carga antes del invierno. Suele durar entre 4 y 6 años.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','revision-bajos','Revisión de bajos y chasis','Revisar',30000,12,null,false,'aproximado','Plazo aproximado','En cada revisión: suspensión, dirección, fuelles de palieres, tubos y latiguillos de freno, escape. Renault lo incluye en sus revisiones, pero no he leído la lista exacta para esta versión.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','caja-cambios','Aceite de caja de cambios','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Renault no suele programar cambio de aceite en las cajas manuales del Kangoo (solo revisar fugas y nivel). No lo he confirmado en el carnet de esta versión.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-12-60','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Kangoo turismo (combi): primera a los 4 años, después cada 2 años y cada año a partir de los 10. Kangoo furgón (Express, N1): primera a los 2 años, cada 2 años hasta los 6, cada año de 6 a 10 y cada 6 meses a partir de los 10.',15);
