insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-16-16v-95','distribucion','Correa de distribución (kit con tensor)','Cambiar',120000,60,null,false,'aproximado','Plazo aproximado','Sin plan Renault leído para el Kangoo I con este motor. El carnet del Kangoo II con el mismo K4M da 120.000 km o 6 años; para el Kangoo I ponemos 5 años, lo que se suele indicar en la época. Si se rompe, el motor se daña.',4);
