insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-80','caja-cambios','Aceite de caja de cambios','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Renault no suele programar cambio de aceite en las cajas manuales del Kangoo (solo revisar fugas y nivel). No lo he confirmado en el carnet de esta versión.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-80','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Kangoo turismo (combi): primera a los 4 años, después cada 2 años y cada año a partir de los 10. Kangoo furgón (Express, N1): primera a los 2 años, cada 2 años hasta los 6, cada año de 6 a 10 y cada 6 meses a partir de los 10.',15);
insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('renault-kangoo-kc-19-dci-85','Renault','Kangoo','KC0/1 (furgón FC0/1)','1.9 dCi 85 CV (también 4x4)',2003,2008,'F9Q','Kangoo I (KC), 2003–2008 · motor F9Q 790 1870 cc, common rail, 84–85 CV · diésel','diesel',62,'[["Motor", "F9Q 790, 4 cilindros, 1870 cc, common rail, 62 kW (84–85 CV)"], ["Distribución", "Por correa (F9Q). Cambio cada 120.000 km o 5 años según el plan que aplica a esta versión. Plazo no confirmado en documento Renault."], ["Aceite motor", "Aceite 5W-40 o 10W-40, norma Renault RN0710 o ACEA B4"], ["Neumáticos", "165/70 R14 o 175/65 R14 según versión (mira la etiqueta del marco de la puerta)"], ["Frenos", "Delante disco; detrás tambor (los 4x4 y algunas versiones pueden variar)"], ["Líquido de frenos", "DOT 4"]]'::jsonb);
