insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-85','aceite','Aceite de motor y filtro','Cambiar',20000,12,null,false,'aproximado','Plazo aproximado','Sin plan Renault leído para este motor. Ponemos 20.000 km o 1 año, lo habitual en los diésel Renault de la época; si tu libro de mantenimiento dice otra cosa, manda el libro.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-85','filtro-aire','Filtro de aire del motor','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Como el 1.9 D de la misma época (plan Clio II). No confirmado para este motor.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-85','filtro-gasoil','Filtro de gasoil','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Motor common rail: el gasoil limpio es vital. Ponemos 60.000 km o 4 años como en el 1.5 dCi del Kangoo II; no confirmado para este motor. Purga el agua si tiene grifo.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-85','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Plazo habitual Renault. No confirmado para este motor.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-85','distribucion','Correa de distribución (kit con tensor)','Cambiar',120000,60,null,false,'aproximado','Plazo aproximado','En el foro Planète Renault confirman 120.000 km o 5 años para el Kangoo 1.9 dCi, pero sin citar documento Renault; otro hilo habla de 75.000 km en un dTi. No lo he podido confirmar en un plan oficial. Renault pide cambiar también la polea del árbol de levas en el primer cambio.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-85','correa','Correa de accesorios (alternador)','Cambiar',120000,60,null,false,'aproximado','Plazo aproximado','Lo habitual es cambiarla junto con la distribución.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-85','frenos-liquido','Líquido de frenos','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Como el 1.9 D de la misma época (plan Clio II): 4 años.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-85','refrigerante','Líquido refrigerante','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Como el 1.9 D de la misma época (plan Clio II): 4 años o 60.000 km. No confirmado.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-85','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Revisar en cada revisión. Cambiar pastillas con menos de 3 mm de material. En furgonetas cargadas o en ciudad se gastan antes.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-85','frenos-traseros','Revisar frenos traseros (tambor o disco según versión)','Revisar',40000,24,null,false,'aproximado','Plazo aproximado','La mayoría lleva tambor detrás; algunas versiones llevan disco. Revisar desgaste y ajuste del freno de mano.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-19-dci-85','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no de Renault. Presión una vez al mes (más si vas cargado: mira la etiqueta del marco de la puerta). Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',10);
