insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Plazo habitual Renault. No confirmado para esta versión.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','distribucion','Correa de distribución (kit con tensor y bomba)','Cambiar',120000,60,null,false,'aproximado','Plazo aproximado','Para el 1.5 dCi de 2001–2005 se da 120.000 km o 5 años (recopilación L''argus para el Clio con este motor y foros Renault), sin documento Renault leído. Desde 2006 aprox. Renault lo subió a 160.000 km o 6 años: si tu libro de mantenimiento dice 160.000, vale ese. Si se rompe, el motor se daña.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','correa','Correa de accesorios (alternador)','Cambiar',120000,60,null,false,'aproximado','Plazo aproximado','Lo habitual es cambiarla junto con la distribución.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','frenos-liquido','Líquido de frenos','Cambiar',120000,48,null,false,'aproximado','Plazo aproximado','Renault pide cada 4 años en los Kangoo II. Absorbe humedad aunque hagas pocos km.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','refrigerante','Líquido refrigerante','Cambiar',120000,60,null,false,'aproximado','Plazo aproximado','Sin plan leído. Cada 5 años o 120.000 km es lo prudente.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','Revisar en cada revisión. Cambiar pastillas con menos de 3 mm de material. En furgonetas cargadas o en ciudad se gastan antes.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','frenos-traseros','Revisar frenos traseros (tambor o disco según versión)','Revisar',40000,24,null,false,'aproximado','Plazo aproximado','La mayoría lleva tambor detrás; algunas versiones llevan disco. Revisar desgaste y ajuste del freno de mano.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no de Renault. Presión una vez al mes (más si vas cargado: mira la etiqueta del marco de la puerta). Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar carga antes del invierno. Suele durar entre 4 y 6 años.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','revision-bajos','Revisión de bajos y chasis','Revisar',15000,12,null,false,'aproximado','Plazo aproximado','En cada revisión: suspensión, dirección, fuelles de palieres, tubos y latiguillos de freno, escape. Renault lo incluye en sus revisiones, pero no he leído la lista exacta para esta versión.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','caja-cambios','Aceite de caja de cambios','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Renault no suele programar cambio de aceite en las cajas manuales del Kangoo (solo revisar fugas y nivel). No lo he confirmado en el carnet de esta versión.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-65','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Kangoo turismo (combi): primera a los 4 años, después cada 2 años y cada año a partir de los 10. Kangoo furgón (Express, N1): primera a los 2 años, cada 2 años hasta los 6, cada año de 6 a 10 y cada 6 meses a partir de los 10.',15);
insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('renault-kangoo-kc-15-dci-70','Renault','Kangoo','KC0/1 (furgón FC0/1)','1.5 dCi 70 CV',2005,2008,'K9K 714','Kangoo I (KC), 2005–2008 · motor K9K 714 1461 cc, common rail, 70 CV · diésel','diesel',50,'[["Motor", "K9K 714, 4 cilindros, 1461 cc, common rail, 50 kW (70 CV)"], ["Distribución", "Por correa (K9K). Cambio cada 120.000 km o 5 años según el plan que aplica a esta versión. Desde 2006 aprox. Renault da 160.000 km o 6 años: manda tu libro de mantenimiento. Correa de 123 dientes."], ["Aceite motor", "Aceite 5W-40 o 10W-40, norma Renault RN0710 o ACEA B4"], ["Neumáticos", "165/70 R14 o 175/65 R14 según versión (mira la etiqueta del marco de la puerta)"], ["Frenos", "Delante disco; detrás tambor (los 4x4 y algunas versiones pueden variar)"], ["Líquido de frenos", "DOT 4"]]'::jsonb);
