insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-85','aceite','Aceite de motor y filtro','Cambiar',20000,12,null,false,'aproximado','Plazo aproximado','El 1.5 dCi sin filtro de partículas del Kangoo II tiene plan Renault de 20.000 km o 1 año; el del Kangoo I es el mismo motor y época parecida, pero no he leído su plan. Si tu libro de mantenimiento dice otra cosa, manda el libro.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-85','filtro-aire','Filtro de aire del motor','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Plazo habitual Renault para el 1.5 dCi. No confirmado para el Kangoo I.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-85','filtro-gasoil','Filtro de gasoil','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Como el 1.5 dCi del Kangoo II (plan Renault: 60.000 km). Purga el agua si tiene grifo.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-85','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Plazo habitual Renault. No confirmado para esta versión.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-85','distribucion','Correa de distribución (kit con tensor y bomba)','Cambiar',120000,60,null,false,'aproximado','Plazo aproximado','Para el 1.5 dCi de 2001–2005 se da 120.000 km o 5 años (recopilación L''argus para el Clio con este motor y foros Renault), sin documento Renault leído. Desde 2006 aprox. Renault lo subió a 160.000 km o 6 años: si tu libro de mantenimiento dice 160.000, vale ese. Si se rompe, el motor se daña.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-85','correa','Correa de accesorios (alternador)','Cambiar',120000,60,null,false,'aproximado','Plazo aproximado','Lo habitual es cambiarla junto con la distribución.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kc-15-dci-85','frenos-liquido','Líquido de frenos','Cambiar',120000,48,null,false,'aproximado','Plazo aproximado','Renault pide cada 4 años en los Kangoo II. Absorbe humedad aunque hagas pocos km.',6);
