insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-16-16v-105','bujias','Bujías','Cambiar',90000,48,null,false,'fabricante','Plan Renault','Carnet Kangoo II 1.6 16V: en la revisión general, cada 90.000 km o 4 años.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-16-16v-105','distribucion','Correa de distribución (kit con tensor y bomba)','Cambiar',120000,72,null,false,'fabricante','Plan Renault','Carnet Kangoo II 1.6 16V: kit de distribución a los 120.000 km o 6 años. Para el Kangoo I con el mismo motor se suele dar 5 años. Si se rompe, el motor se daña.',4);
