insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-16-16v-105','frenos-liquido','Líquido de frenos','Cambiar',120000,48,null,false,'fabricante','Plan Renault','Carnet Kangoo II 1.6 16V: cada 4 años o 120.000 km.',6);
