insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-70','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Kangoo turismo (combi): primera a los 4 años, después cada 2 años y cada año a partir de los 10. Kangoo furgón (Express, N1): primera a los 2 años, cada 2 años hasta los 6, cada año de 6 a 10 y cada 6 meses a partir de los 10.',15);
