insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-85','aceite','Aceite de motor y filtro','Cambiar',20000,12,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia; es el mismo motor sin filtro de partículas que el dCi 70, cuyo carnet (idgarages) dice: revisión con aceite y filtro cada 20.000 km o 1 año.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-85','filtro-aire','Filtro de aire del motor','Cambiar',80000,24,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia; es el mismo motor sin filtro de partículas que el dCi 70, cuyo carnet (idgarages) dice: filtro de aire en la revisión general, cada 80.000 km (o 2 años).',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-85','filtro-gasoil','Filtro de gasoil','Cambiar',60000,null,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia; es el mismo motor sin filtro de partículas que el dCi 70, cuyo carnet (idgarages) dice: filtro de gasoil cada 60.000 km. Purga el agua si tiene grifo.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-85','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',40000,24,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia; es el mismo motor sin filtro de partículas que el dCi 70, cuyo carnet (idgarages) dice: cada 40.000 km.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-85','distribucion','Correa de distribución (kit con tensor y bomba)','Cambiar',160000,72,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia; es el mismo motor sin filtro de partículas que el dCi 70, cuyo carnet (idgarages) dice: kit de distribución a los 160.000 km o 6 años. Coincide con Haynes para el dCi 105 del Kangoo II y con Actu-Automobile para el 1.5 dCi desde 2006. Si se rompe, el motor se daña.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-85','correa','Correa de accesorios (alternador)','Cambiar',160000,72,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia; es el mismo motor sin filtro de partículas que el dCi 70, cuyo carnet (idgarages) dice: junto con la distribución, 160.000 km o 6 años.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-85','frenos-liquido','Líquido de frenos','Cambiar',120000,48,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia; es el mismo motor sin filtro de partículas que el dCi 70, cuyo carnet (idgarages) dice: cada 120.000 km o 4 años.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-85','refrigerante','Líquido refrigerante','Cambiar',160000,72,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia; es el mismo motor sin filtro de partículas que el dCi 70, cuyo carnet (idgarages) dice: cada 160.000 km o 6 años.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-85','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','Revisar en cada revisión. Cambiar pastillas con menos de 3 mm de material. En furgonetas cargadas o en ciudad se gastan antes.',8);
