insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','aceite','Aceite de motor y filtro','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia. Para el 1.5 dCi 105 con filtro de partículas del mismo Kangoo II, Renault (vía Haynes) da: aceite cada 30.000 km o 2 años (los fabricados hasta enero de 2009 tenían 1 año). Usa aceite de bajas cenizas (Renault RN0720) por el filtro de partículas.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','filtro-aire','Filtro de aire del motor','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia. Para el 1.5 dCi 105 con filtro de partículas del mismo Kangoo II, Renault (vía Haynes) da: filtro de aire cada 60.000 km o 4 años.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','filtro-gasoil','Filtro de gasoil','Cambiar',60000,null,null,false,'aproximado','Plazo aproximado','Haynes no lo muestra; el carnet del dCi 70 del Kangoo II lo cambia cada 60.000 km. Purga el agua si tiene grifo.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia. Para el 1.5 dCi 105 con filtro de partículas del mismo Kangoo II, Renault (vía Haynes) da: filtro de polen cada 30.000 km.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','distribucion','Correa de distribución (kit con tensor y bomba)','Cambiar',160000,72,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia. Para el 1.5 dCi 105 con filtro de partículas del mismo Kangoo II, Renault (vía Haynes) da: correa de distribución cada 160.000 km o 6 años. Coincide con el carnet del dCi 70 (idgarages). Si se rompe, el motor se daña.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','correa','Correa de accesorios (alternador)','Cambiar',160000,72,null,false,'aproximado','Plazo aproximado','El carnet del dCi 70 la cambia junto con la distribución (160.000 km o 6 años).',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','frenos-liquido','Líquido de frenos','Cambiar',120000,48,null,false,'aproximado','Plazo aproximado','Sin plan leído para esta potencia. Para el 1.5 dCi 105 con filtro de partículas del mismo Kangoo II, Renault (vía Haynes) da: líquido de frenos cada 120.000 km o 4 años.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','refrigerante','Líquido refrigerante','Cambiar',160000,72,null,false,'aproximado','Plazo aproximado','Haynes solo pide revisar; el carnet del dCi 70 lo cambia a los 160.000 km o 6 años.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','Revisar en cada revisión. Cambiar pastillas con menos de 3 mm de material. En furgonetas cargadas o en ciudad se gastan antes.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','frenos-traseros','Revisar frenos traseros (tambor o disco según versión)','Revisar',40000,24,null,false,'aproximado','Plazo aproximado','La mayoría lleva tambor detrás; algunas versiones llevan disco. Revisar desgaste y ajuste del freno de mano.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no de Renault. Presión una vez al mes (más si vas cargado: mira la etiqueta del marco de la puerta). Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar carga antes del invierno. Suele durar entre 4 y 6 años.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','revision-bajos','Revisión de bajos y chasis','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','En cada revisión: suspensión, dirección, fuelles de palieres, tubos y latiguillos de freno, escape. Renault lo incluye en sus revisiones, pero no he leído la lista exacta para esta versión.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','caja-cambios','Aceite de caja de cambios','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Renault no suele programar cambio de aceite en las cajas manuales del Kangoo (solo revisar fugas y nivel). No lo he confirmado en el carnet de esta versión.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-75','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Kangoo turismo (combi): primera a los 4 años, después cada 2 años y cada año a partir de los 10. Kangoo furgón (Express, N1): primera a los 2 años, cada 2 años hasta los 6, cada año de 6 a 10 y cada 6 meses a partir de los 10.',15);
