insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-110','frenos-traseros','Revisar frenos traseros (tambor o disco según versión)','Revisar',40000,24,null,false,'aproximado','Plazo aproximado','La mayoría lleva tambor detrás; algunas versiones llevan disco. Revisar desgaste y ajuste del freno de mano.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-110','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no de Renault. Presión una vez al mes (más si vas cargado: mira la etiqueta del marco de la puerta). Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-110','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-110','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar carga antes del invierno. Suele durar entre 4 y 6 años.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-110','revision-bajos','Revisión de bajos y chasis','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','En cada revisión: suspensión, dirección, fuelles de palieres, tubos y latiguillos de freno, escape. Renault lo incluye en sus revisiones, pero no he leído la lista exacta para esta versión.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-110','caja-cambios','Aceite de caja de cambios','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Renault no suele programar cambio de aceite en las cajas manuales del Kangoo (solo revisar fugas y nivel). No lo he confirmado en el carnet de esta versión.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-dci-110','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Kangoo turismo (combi): primera a los 4 años, después cada 2 años y cada año a partir de los 10. Kangoo furgón (Express, N1): primera a los 2 años, cada 2 años hasta los 6, cada año de 6 a 10 y cada 6 meses a partir de los 10.',15);
insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('renault-kangoo-kw-15-bluedci-80','Renault','Kangoo','KW0/1 (furgón FW0/1)','1.5 Blue dCi 80 CV',2019,2021,'K9K (Blue dCi)','Kangoo II (KW), 2019–2021 · motor K9K (Blue dCi) 1461 cc, common rail, 80 CV con filtro de partículas · diésel','diesel',59,'[["Motor", "K9K (Blue dCi), 4 cilindros, 1461 cc, common rail, 59 kW (80 CV), con filtro de partículas (FAP)"], ["Distribución", "Por correa (K9K). Cambio cada 160.000 km o 6 años según el plan que aplica a esta versión. Plazo no confirmado para el Blue dCi."], ["Aceite motor", "Aceite 5W-30, norma Renault RN17"], ["Neumáticos", "195/65 R15 en la mayoría; algunas versiones 205/60 R16 (mira la etiqueta del marco de la puerta)"], ["Frenos", "Delante disco; detrás tambor o disco según versión"], ["Líquido de frenos", "DOT 4"]]'::jsonb);
