insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-bluedci-115','aceite','Aceite de motor y filtro','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Sin plan leído para el Blue dCi del Kangoo II. Renault (vía Haynes) da 30.000 km o 2 años al mismo motor en el Kangoo III y al dCi 105 del Kangoo II. Aceite de bajas cenizas (Renault RN17).',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-bluedci-115','filtro-aire','Filtro de aire del motor','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Como el Blue dCi del Kangoo III (plan Renault: 60.000 km o 4 años).',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-bluedci-115','filtro-gasoil','Filtro de gasoil','Cambiar',60000,48,null,false,'aproximado','Plazo aproximado','Sin plan leído. 60.000 km como el dCi del Kangoo II.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-bluedci-115','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',30000,24,null,false,'aproximado','Plazo aproximado','Como el Kangoo III (plan Renault: 30.000 km o 2 años).',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-bluedci-115','distribucion','Correa de distribución (kit con tensor y bomba)','Cambiar',160000,72,null,false,'aproximado','Plazo aproximado','No he encontrado el plazo Renault para el Blue dCi. Los 1.5 dCi anteriores del Kangoo II llevan 160.000 km o 6 años y lo dejamos igual; mira tu libro de mantenimiento y, si da otro plazo, sigue el libro. Si se rompe, el motor se daña.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-bluedci-115','correa','Correa de accesorios (alternador)','Cambiar',160000,72,null,false,'aproximado','Plazo aproximado','Junto con la distribución.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-kw-15-bluedci-115','frenos-liquido','Líquido de frenos','Cambiar',120000,48,null,false,'aproximado','Plazo aproximado','Renault pide cada 4 años en el resto de Kangoo II y III.',6);
