insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-k3-15-bluedci-95','distribucion','Correa de distribución (kit con tensor y bomba)','Cambiar',160000,72,null,false,'aproximado','Plazo aproximado','El plan Renault del Kangoo III (vía Haynes) no muestra el cambio de correa en sus tablas, así que el plazo es mayor que el que cubren. No he encontrado la cifra oficial: ponemos 160.000 km o 6 años como los 1.5 dCi anteriores. Mira tu libro de mantenimiento.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-k3-15-bluedci-95','correa','Correa de accesorios (alternador)','Cambiar',160000,72,null,false,'aproximado','Plazo aproximado','Junto con la distribución.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-k3-15-bluedci-95','adblue','AdBlue: rellenar','Revisar',null,null,null,true,'aproximado','Plazo aproximado','El Blue dCi usa AdBlue. Rellénalo cuando avise el cuadro; si se vacía, el coche no arranca.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-k3-15-bluedci-95','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','Revisar en cada revisión. Cambiar pastillas con menos de 3 mm de material. En furgonetas cargadas o en ciudad se gastan antes.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-k3-15-bluedci-95','frenos-traseros','Revisar frenos traseros (tambor o disco según versión)','Revisar',40000,24,null,false,'aproximado','Plazo aproximado','La mayoría lleva tambor detrás; algunas versiones llevan disco. Revisar desgaste y ajuste del freno de mano.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-k3-15-bluedci-95','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no de Renault. Presión una vez al mes (más si vas cargado: mira la etiqueta del marco de la puerta). Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-k3-15-bluedci-95','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-k3-15-bluedci-95','bateria','Batería de 12 V: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar carga antes del invierno. Suele durar entre 4 y 6 años.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-k3-15-bluedci-95','revision-bajos','Revisión de bajos y chasis','Revisar',30000,24,null,false,'aproximado','Plazo aproximado','En cada revisión: suspensión, dirección, fuelles de palieres, tubos y latiguillos de freno, escape. Renault lo incluye en sus revisiones, pero no he leído la lista exacta para esta versión.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-k3-15-bluedci-95','caja-cambios','Aceite de caja de cambios','Sin cambio programado',null,null,null,true,'aproximado','Plazo aproximado','Renault no suele programar cambio de aceite en las cajas manuales del Kangoo (solo revisar fugas y nivel). No lo he confirmado en el carnet de esta versión.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('renault-kangoo-k3-15-bluedci-95','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Kangoo turismo (combi): primera a los 4 años, después cada 2 años y cada año a partir de los 10. Kangoo furgón (Express, N1): primera a los 2 años, cada 2 años hasta los 6, cada año de 6 a 10 y cada 6 meses a partir de los 10.',16);
